const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/1';

// 1. Extraer datos del webhook de forma segura
let webhookBody = {};
try {
  const wh = $('Webhook').first().json;
  webhookBody = wh.body || wh;
} catch (e) {
  try {
    const inp = $input.first().json;
    webhookBody = inp.body || inp;
  } catch (e2) {
    webhookBody = {};
  }
}

const conversation = webhookBody.conversation || {};
const account = webhookBody.account || {};
const inbox = webhookBody.inbox || {};
const conversationId = conversation.id || webhookBody.id || 13;
const accountId = account.id || 1;
const content = webhookBody.content || '';
const channel = conversation.channel || inbox.channel_type || '';
let labels = Array.isArray(conversation.labels) ? conversation.labels : [];
let inboxId = Number(inbox.id || conversation.inbox_id || 0);

// 2. Consultar conversación, mensajes y contacto en Chatwoot API
let convData = {};
let contactData = {};
let contactId = null;

try {
  convData = await this.helpers.httpRequest({
    method: 'GET',
    url: chatwootBase + '/conversations/' + conversationId,
    headers: { 'api_access_token': chatwootToken },
    json: true
  });
  if (convData) {
    inboxId = Number(convData.inbox_id || inboxId || 0);
    if (Array.isArray(convData.labels)) {
      labels = convData.labels;
    }
    contactId = convData.meta?.sender?.id || convData.contact_id;
  }
} catch (e) {}

// Obtener todos los mensajes de la conversación
let allMessages = [];
try {
  const msgsRes = await this.helpers.httpRequest({
    method: 'GET',
    url: chatwootBase + '/conversations/' + conversationId + '/messages',
    headers: { 'api_access_token': chatwootToken },
    json: true
  });
  if (msgsRes && Array.isArray(msgsRes.payload)) {
    allMessages = msgsRes.payload;
  }
} catch (e) {}

// 3. ROLLING DEBOUNCE (espera dinámica de 5 segundos con reinicio por cada nuevo escrito):
const incomingMsgs = allMessages.filter(m => m.message_type === 0 || (m.sender && m.sender.type === 'user'));
let lastIncomingTimestamp = 0;
if (incomingMsgs.length > 0) {
  const lastMsg = incomingMsgs[incomingMsgs.length - 1];
  lastIncomingTimestamp = lastMsg.created_at ? (lastMsg.created_at * 1000) : 0;
}

const nowMs = Date.now();
const elapsedMs = nowMs - lastIncomingTimestamp;

// Si el último escrito del cliente llegó hace menos de 4.5 segundos, significa que llegó otro mensaje
// mientras esta ejecución esperaba sus 5s. Cedemos el turno a la ejecución más reciente para evitar respuestas duplicadas.
if (lastIncomingTimestamp > 0 && elapsedMs < 4500) {
  return [{
    json: {
      conversation_id: conversationId,
      skip_ai_response: true,
      reason: 'rolling_debounce_yield_to_newer_message'
    }
  }];
}

if (contactId) {
  try {
    const ctRes = await this.helpers.httpRequest({
      method: 'GET',
      url: chatwootBase + '/contacts/' + contactId,
      headers: { 'api_access_token': chatwootToken },
      json: true
    });
    contactData = ctRes?.payload || {};
  } catch (e) {}
}

const isHuman = labels.includes('human');

// Auto-asignación a Agent 3 y Team 1
try {
  const currentAssigneeId = convData?.meta?.assignee?.id;
  const currentTeamId = convData?.meta?.team?.id;
  if (currentAssigneeId !== 3 || currentTeamId !== 1) {
    await this.helpers.httpRequest({
      method: 'POST',
      url: chatwootBase + '/conversations/' + conversationId + '/assignments',
      headers: {
        'api_access_token': chatwootToken,
        'Content-Type': 'application/json'
      },
      body: { assignee_id: 3, team_id: 1 },
      json: true
    });
  }
} catch (e) {}

// 4. Inboxes y etiquetas
const isTVTotal24 = (inboxId === 10 || inboxId === 13 || inboxId === 15 || inboxId === 16 || inboxId === 19);
const brand = isTVTotal24 ? 'tvtotal24' : 'totaltvusa';

let updatedLabels = [...labels];
let needsLabelUpdate = false;

if (updatedLabels.includes('autoclosed')) {
  updatedLabels = updatedLabels.filter(l => l !== 'autoclosed');
  needsLabelUpdate = true;
}

if (isTVTotal24) {
  if (updatedLabels.includes('funnel-totaltv-usa')) {
    updatedLabels = updatedLabels.filter(l => l !== 'funnel-totaltv-usa');
    needsLabelUpdate = true;
  }
  if (!updatedLabels.includes('funnel-totaltv-latina')) {
    updatedLabels.push('funnel-totaltv-latina');
    needsLabelUpdate = true;
  }
  if (inboxId === 19) {
    updatedLabels = updatedLabels.filter(l => l !== 'channel-whatsapp');
    if (!updatedLabels.includes('channel-officialwhatsapp')) {
      updatedLabels.push('channel-officialwhatsapp');
      needsLabelUpdate = true;
    }
  } else if (inboxId === 16) {
    updatedLabels = updatedLabels.filter(l => l !== 'channel-whatsapp');
    if (!updatedLabels.includes('channel-whatsapp-lite')) {
      updatedLabels.push('channel-whatsapp-lite');
      needsLabelUpdate = true;
    }
  } else if (inboxId === 13 && !updatedLabels.includes('channel-instagram')) {
    updatedLabels.push('channel-instagram');
    needsLabelUpdate = true;
  } else if (inboxId === 10 && !updatedLabels.includes('channel-telegram')) {
    updatedLabels.push('channel-telegram');
    needsLabelUpdate = true;
  } else if (inboxId === 15 && !updatedLabels.includes('channel-tiktok')) {
    updatedLabels.push('channel-tiktok');
    needsLabelUpdate = true;
  }
} else {
  if (updatedLabels.includes('funnel-totaltv-latina')) {
    updatedLabels = updatedLabels.filter(l => l !== 'funnel-totaltv-latina');
    needsLabelUpdate = true;
  }
  if (!updatedLabels.includes('funnel-totaltv-usa')) {
    updatedLabels.push('funnel-totaltv-usa');
    needsLabelUpdate = true;
  }
  if (inboxId === 18) {
    if (!updatedLabels.includes('channel-whatsapp-lite')) {
      updatedLabels.push('channel-whatsapp-lite');
      needsLabelUpdate = true;
    }
  } else if (inboxId === 17 || channel.toLowerCase().includes('facebook')) {
    if (!updatedLabels.includes('channel-facebook')) {
      updatedLabels.push('channel-facebook');
      needsLabelUpdate = true;
    }
  } else if (inboxId === 14 && !updatedLabels.includes('channel-instagram')) {
    updatedLabels.push('channel-instagram');
    needsLabelUpdate = true;
  } else if (inboxId === 6 && !updatedLabels.includes('channel-telegram')) {
    updatedLabels.push('channel-telegram');
    needsLabelUpdate = true;
  } else if (inboxId === 4 && !updatedLabels.includes('channel-whatsapp')) {
    updatedLabels.push('channel-whatsapp');
    needsLabelUpdate = true;
  }
}

if (needsLabelUpdate) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: chatwootBase + '/conversations/' + conversationId + '/labels',
      headers: {
        'api_access_token': chatwootToken,
        'Content-Type': 'application/json'
      },
      body: { labels: updatedLabels },
      json: true
    });
  } catch (e) {}
}

// 5. AGREGACIÓN DE MENSAJES Y ADJUNTOS DE LA RÁFAGA (últimos 2 minutos desde el último mensaje del asistente)
let lastOutgoingTimestamp = 0;
for (let i = allMessages.length - 1; i >= 0; i--) {
  if (allMessages[i].message_type === 1) {
    lastOutgoingTimestamp = allMessages[i].created_at ? (allMessages[i].created_at * 1000) : 0;
    break;
  }
}

const recentIncoming = incomingMsgs.filter(m => {
  const mTime = m.created_at ? (m.created_at * 1000) : 0;
  return mTime > lastOutgoingTimestamp && (nowMs - mTime) < 120000;
});

let combinedTextParts = [];
let collectedImageAttachments = [];

if (recentIncoming.length > 0) {
  for (const msg of recentIncoming) {
    if (msg.content && msg.content.trim()) {
      combinedTextParts.push(msg.content.trim());
    }
    if (Array.isArray(msg.attachments)) {
      for (const att of msg.attachments) {
        if (att.file_type === 'image' || (att.content_type && att.content_type.startsWith('image')) || (att.data_url && /\.(jpeg|jpg|png|webp)/i.test(att.data_url))) {
          collectedImageAttachments.push(att);
        }
      }
    }
  }
}

const webhookAtts = webhookBody.attachments || (webhookBody.conversation?.messages?.[0]?.attachments) || [];
for (const att of webhookAtts) {
  if (att.file_type === 'image' || (att.content_type && att.content_type.startsWith('image')) || (att.data_url && /\.(jpeg|jpg|png|webp)/i.test(att.data_url))) {
    if (!collectedImageAttachments.some(a => a.data_url === att.data_url)) {
      collectedImageAttachments.push(att);
    }
  }
}

let fullContent = combinedTextParts.join('\n');
if (!fullContent && content) {
  fullContent = content;
}

let hasImage = false;
let base64Image = '';
let mediaType = 'image/jpeg';

if (collectedImageAttachments.length > 0) {
  const imageUrl = collectedImageAttachments[0].data_url || collectedImageAttachments[0].thumb_url;
  if (imageUrl) {
    if (imageUrl.toLowerCase().includes('.png')) mediaType = 'image/png';
    else if (imageUrl.toLowerCase().includes('.webp')) mediaType = 'image/webp';
    try {
      const imgBuffer = await this.helpers.httpRequest({
        url: imageUrl,
        encoding: null
      });
      base64Image = Buffer.from(imgBuffer).toString('base64');
      if (base64Image) {
        hasImage = true;
      }
    } catch (e) {}
  }
}

let rawPhone = contactData.phone_number || convData?.meta?.sender?.phone_number || '';
if (!rawPhone && contactData.identifier) {
  const ident = String(contactData.identifier);
  if (ident.includes('@s.whatsapp.net') || ident.includes('@c.us') || /^\+?\d[\d\s-]{6,}$/.test(ident)) {
    rawPhone = ident;
  }
}

const contactPhone = String(rawPhone || '').trim();
const contactEmail = String(contactData.email || convData?.meta?.sender?.email || '').trim();
const contactName = String(contactData.name || convData?.meta?.sender?.name || '').trim();
const contactBio = String(contactData.additional_attributes?.description || '').trim();
const contactAdditionalAttrs = contactData.additional_attributes || convData?.meta?.sender?.additional_attributes || {};
const contactCompanyName = String(contactAdditionalAttrs.company_name || '').trim();

const isAlreadyLeadsGanados = updatedLabels.includes('stage-leads-ganados') || updatedLabels.includes('leads-ganados');
const canBypassSheet = isAlreadyLeadsGanados && Boolean(contactCompanyName) && Boolean(contactBio);

const isNumericName = /^\+?\d[\d\s-]{5,}$/.test(String(contactName || '').trim());
const isValidPersonName = contactName && contactName !== 'Customer' && contactName !== 'Desconocido' && !isNumericName;

let clientContextPrefix = '';
if (isAlreadyLeadsGanados) {
  clientContextPrefix = `[CLIENT CONTEXT: Existing customer in database (stage-leads-ganados). Full Name: "${contactName || 'Customer'}", Email: "${contactEmail || ''}", Phone: "${contactPhone || ''}", 1ra Compra: "${contactBio || ''}". RULES FOR THIS CLIENT: 1. NEVER proactively offer free trials. 2. If customer asks for a trial: check if for someone else in history, or confirm if for themselves (using registered data directly without re-asking) or for a family/friend (to collect recipient data). 3. If customer reports a technical issue or payment/account issue, DO NOT transfer immediately; perform technical or administrative triage first. 4. If customer explicitly asks for a human advisor, transfer without re-asking contact data.]\n\n`;
} else {
  const knownName = isValidPersonName ? contactName : '';
  const knownPhone = contactPhone ? contactPhone : '';
  let idInfo = [];
  if (knownName) idInfo.push(`Name: "${knownName}"`);
  if (knownPhone) idInfo.push(`Phone: "${knownPhone}"`);
  if (idInfo.length > 0) {
    clientContextPrefix = `[CLIENT CONTEXT: Known Contact info - ${idInfo.join(', ')}. (Note: For human transfer, customer Name and Phone must be known. If reporting issues or payments, perform technical/administrative triage first. If customer requests a free trial, collect full name with at least 2 words, email, and phone with country code)]\n\n`;
  }
}

return [{
  json: {
    conversation_id: conversationId,
    account_id: accountId,
    inbox_id: inboxId,
    contact_id: contactId,
    brand: brand,
    channel: channel,
    message: fullContent,
    content: clientContextPrefix + fullContent,
    raw_content: fullContent,
    contact_phone: contactPhone,
    contact_email: contactEmail,
    contact_name: contactName,
    contact_bio: contactBio,
    contact_additional_attributes: contactAdditionalAttrs,
    contact_company_name: contactCompanyName,
    labels: updatedLabels,
    already_leads_ganados: canBypassSheet,
    is_lead_ganado: isAlreadyLeadsGanados,
    is_human: isHuman,
    skip_ai_response: isHuman,
    has_image: hasImage,
    base64_image: base64Image,
    media_type: mediaType
  }
}];

// 1. Obtener la respuesta de la IA
const aiResponse = $input.item.json.output || $input.item.json.text || $input.item.json.response || "";

// 2. Extraer datos del webhook de forma segura (.first() en vez de .item)
let webhookRaw = {};
let webhookBody = {};
try {
  webhookRaw = $('Webhook').first().json || {};
  webhookBody = webhookRaw.body ? webhookRaw.body : webhookRaw;
} catch (e) {
  webhookBody = {};
}

const conversation = webhookBody.conversation || {};
const account = webhookBody.account || {};
const inbox = webhookBody.inbox || {};
const conversationId = conversation.id || 13;
const accountId = account.id || 1;
const inboxId = Number(inbox.id || conversation.inbox_id || 0);
const channel = conversation.channel || inbox.channel_type || "";

let formattedText = aiResponse;

// Sanitizar posibles alucinaciones de fallo al transferir (ej. "inconveniente técnico momentáneo... volveré a intentar")
const transferErrorRegex = /(?:inconveniente t[eé]cnico moment[aá]neo|no se pudo (?:hacer la )?transferencia|error al transferir|volver[eé] a intentar la transferencia|failed to transfer|momentary technical issue)/i;
if (transferErrorRegex.test(formattedText)) {
  const isEn = /\b(the|and|you|have|your|support|team|hours)\b/i.test(formattedText);
  if (isEn) {
    formattedText = "I have transferred your request to our human support team. An agent will assist you shortly within our extended office hours. Thank you for your patience!";
  } else {
    formattedText = "Te he transferido con nuestro equipo de soporte humano. Un asesor te atenderá a la brevedad posible dentro de nuestro horario extendido de oficina. ¡Muchas gracias por tu paciencia!";
  }
}

// Verificar si en esta ejecución se invocó la transferencia a humano
let transferToolCalled = false;
try {
  const toolData = $('Call \'transfer_to_human_tool\'').first();
  if (toolData && toolData.json) {
    transferToolCalled = true;
  }
} catch (e) {
  // El nodo no fue ejecutado en este run
}

// Si se llamó la tool de transferencia pero el texto no menciona la transferencia al cliente, garantizar el aviso explícito
if (transferToolCalled) {
  const mentionsTransfer = /(?:transferid[oa]|transferencia|transferir|soporte humano|asesor humano|human support|transferred|representative|human agent)/i.test(formattedText);
  if (!mentionsTransfer) {
    const isEn = /\b(the|and|you|have|your|support|team|hours)\b/i.test(formattedText);
    if (isEn) {
      formattedText = (formattedText ? formattedText.trim() + "\n\n" : "") + "I have transferred your conversation to our human support team. An agent will assist you shortly within our extended office hours. Thank you for your patience!";
    } else {
      formattedText = (formattedText ? formattedText.trim() + "\n\n" : "") + "Te he transferido con nuestro equipo de soporte humano. Un asesor te atenderá a la brevedad posible dentro de nuestro horario extendido de oficina. ¡Muchas gracias por tu paciencia!";
    }
  }
}

// Sanitizar mezcla de idiomas en planes si la respuesta es en inglés
try {
  const enPattern = /\b(here(?:'?s| is)|plans|pricing|breakdown|subscription|devices?|months?|which|purchase|longer|value|enjoy|welcome|hello|free|trial|interested|please)\b/gi;
  const esPattern = /\b(aquí|planes|precios|suscripci[oó]n|cu[aá]l|deseas?|bienvenido|hola|gratis|prueba|interesa|favor)\b/gi;
  const enMatches = (formattedText.match(enPattern) || []).length;
  const esMatches = (formattedText.match(esPattern) || []).length;
  if (enMatches >= esMatches && enMatches > 0) {
    formattedText = formattedText.replace(/12\s*Meses\s*\(\s*1\s*A[ñn]o\s*\)/gi, "12 Months (1 Year)");
    formattedText = formattedText.replace(/12\s*Meses/gi, "12 Months");
    formattedText = formattedText.replace(/6\s*Meses/gi, "6 Months");
    formattedText = formattedText.replace(/3\s*Meses/gi, "3 Months");
    formattedText = formattedText.replace(/1\s*Mes/gi, "1 Month");
    formattedText = formattedText.replace(/(\d+)\s*Dispositivos?/gi, (m, d) => `${d} ${d === '1' ? 'Device' : 'Devices'}`);
    formattedText = formattedText.replace(/Contenido\s+Adulto\s+opcional\s*:\s*GRATIS/gi, "Optional Adult Content: FREE");
    formattedText = formattedText.replace(/Contenido\s+Adulto\s+opcional\s*:\s*\+(\$\d+)/gi, "Optional Adult Content: +$1");
    formattedText = formattedText.replace(/Contenido\s+Adulto\s+opcional/gi, "Optional Adult Content");
    formattedText = formattedText.replace(/Dispositivos?/gi, "Devices");
    formattedText = formattedText.replace(/Meses/gi, "Months");
  }
} catch (e) {}

// 3. Formatear según canal (Meta / WhatsApp / Instagram / Facebook vs Telegram)
if (channel.includes("Whatsapp") || channel.includes("Facebook") || channel.includes("Instagram") || channel.includes("Api") || inboxId === 16 || inboxId === 19 || inboxId === 13 || inboxId === 14 || inboxId === 17 || inboxId === 18 || inboxId === 4) {
  formattedText = formattedText.replace(/\*\*(.*?)\*\*/g, '*$1*');
  formattedText = formattedText.replace(/\[(.*?)\]\((.*?)\)/g, '$1: $2');
}

// 4. Activar estado de presencia "composing" (escribiendo) en Chatwoot
try {
  const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
  const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/' + accountId;
  await this.helpers.httpRequest({
    method: 'POST',
    url: chatwootBase + '/conversations/' + conversationId + '/toggle_typing_status',
    headers: {
      'api_access_token': chatwootToken,
      'Content-Type': 'application/json'
    },
    body: { typing_status: 'on' },
    json: true
  });
} catch (e) {
  // Non-blocking
}

// 5. Random delay entre 2 y 5 segundos (para simulación de escritura humana)
const randomDelaySeconds = Math.floor(Math.random() * 4) + 2;

return [{
  json: {
    content: formattedText,
    conversation_id: conversationId,
    account_id: accountId,
    inbox_id: inboxId,
    channel: channel,
    delay_seconds: randomDelaySeconds
  }
}];

try {
  const raw = $input.first()?.json || {};
  const body = raw.body ? raw.body : raw;

  const event = body.event || '';
  const message = body.message || {};
  const direction = message.direction || '';

  if (event !== 'message.received' || direction !== 'incoming') {
    return [{ json: { ignored: true, reason: 'not incoming message.received', event, direction } }];
  }

  // Check account platform: ACCEPT INSTAGRAM AND FACEBOOK
  const account = body.account || {};
  const platform = account.platform || '';
  if (platform !== 'instagram' && platform !== 'facebook') {
    return [{ json: { ignored: true, reason: 'platform is not instagram or facebook', platform } }];
  }

  const text = message.text || '';
  if (!text.trim()) {
    return [{ json: { ignored: true, reason: 'empty text' } }];
  }

  // Determine brand & inbox
  // TVTotal24 Instagram: Account ID 6a8667d577555aae0139eca3 / username tvtotal24 -> Inbox 13, funnel-totaltv-latina
  // TotalTv USA Instagram: Account ID 6a86600b77555aae01387fc7 / username tvtotalusa -> Inbox 14, funnel-totaltv-usa
  // TotalTv USA Facebook: Account ID 6a87b56c77555aae01ddcf1c / username TotalTv2025 -> Inbox 17, funnel-totaltv-usa
  const accountId = account.id || account.accountId || '';
  const accountUsername = account.username || '';

  let inboxId = 13;
  let brandLabel = 'funnel-totaltv-latina';
  let channelLabel = 'channel-instagram';

  if (platform === 'facebook') {
    // Facebook Messenger -> always TotalTv USA Inbox 17
    inboxId = 17;
    brandLabel = 'funnel-totaltv-usa';
    channelLabel = 'channel-facebook';
  } else if (accountId === '6a86600b77555aae01387fc7' || accountUsername.toLowerCase() === 'tvtotalusa') {
    inboxId = 14;
    brandLabel = 'funnel-totaltv-usa';
    channelLabel = 'channel-instagram';
  } else if (accountId === '6a8667d577555aae0139eca3' || accountUsername.toLowerCase() === 'tvtotal24') {
    inboxId = 13;
    brandLabel = 'funnel-totaltv-latina';
    channelLabel = 'channel-instagram';
  } else {
    // Default fallback check
    if (accountUsername.toLowerCase().includes('usa')) {
      inboxId = 14;
      brandLabel = 'funnel-totaltv-usa';
    }
  }

  const sender = message.sender || {};
  const conversation = body.conversation || {};
  const zernioConvId = conversation.id || message.conversationId || '';
  const participantId = conversation.participantId || sender.id || '';
  const participantName = conversation.participantName || sender.name || (platform === 'facebook' ? 'Facebook User ' + participantId : 'Instagram User ' + participantId);
  const participantUsername = conversation.participantUsername || sender.username || '';

  const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
  const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/1';

  // Identifier prefix based on platform
  const identPrefix = platform === 'facebook' ? 'fb_' : 'ig_';

  // 1. Search or create contact in Chatwoot
  let contactId = null;
  try {
    const searchRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `${chatwootBase}/contacts/search?q=${encodeURIComponent(participantId)}`,
      headers: { 'api_access_token': chatwootToken },
      json: true
    });
    const contacts = searchRes.payload || [];
    if (contacts.length > 0) {
      contactId = contacts[0].id;
    }
  } catch (e) {}

  if (!contactId) {
    try {
      const customAttrs = {
        zernio_conversation_id: zernioConvId,
        participant_id: participantId,
        zernio_account_id: accountId,
        zernio_platform: platform
      };
      if (platform === 'facebook') {
        customAttrs.facebook_username = participantUsername;
      } else {
        customAttrs.instagram_username = participantUsername;
      }

      const createContactRes = await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/contacts`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: {
          inbox_id: inboxId,
          name: participantName,
          identifier: `${identPrefix}${participantId}`,
          custom_attributes: customAttrs
        },
        json: true
      });
      contactId = createContactRes.payload?.contact?.id || createContactRes.id;
    } catch (e) {}
  }

  if (!contactId) {
    return [{ json: { error: 'Failed to create/find contact', participantId } }];
  }

  // 2. Find open conversation or create one in the target inbox
  let conversationId = null;
  let existingLabels = [];
  try {
    const convListRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `${chatwootBase}/contacts/${contactId}/conversations`,
      headers: { 'api_access_token': chatwootToken },
      json: true
    });
    const convs = convListRes.payload || [];
    const openConv = convs.find(c => c.inbox_id === inboxId && c.status !== 'resolved');
    if (openConv) {
      conversationId = openConv.id;
      existingLabels = openConv.labels || [];
    }
  } catch (e) {}

  if (!conversationId) {
    const customAttrs = {
      zernio_conversation_id: zernioConvId,
      participant_id: participantId,
      zernio_account_id: accountId,
      zernio_platform: platform
    };
    if (platform === 'facebook') {
      customAttrs.facebook_username = participantUsername;
