  const d1 = cleanPhone(p1);
  const d2 = cleanPhone(p2);
  if (!d1 || !d2 || d1.length < 7 || d2.length < 7) return false;

  if (d1 === d2) return true;
  if (d1.endsWith(d2) || d2.endsWith(d1)) return true;

  if (d1.length >= 10 && d2.length >= 10 && d1.slice(-10) === d2.slice(-10)) return true;
  if (d1.length >= 9 && d2.length >= 9 && d1.slice(-9) === d2.slice(-9)) return true;

