\"reference_number\": \"referencia o ID de orden si aplica\",\n  \"is_app_screenshot_or_error\": true | false,\n  \"app_name\": \"nombre de la app o 'Desconocida'\",\n  \"device_type\": \"tipo de dispositivo o 'Desconocido'\",\n  \"screen_type\": \"pantalla observada\",\n  \"detected_error\": \"mensaje/código de error o 'Ninguno'\",\n  \"app_diagnosis_summary\": \"diagnóstico técnico y solución recomendada\",\n  \"raw_summary\": \"resumen general\"\n}"
