parameters.jsCode:
// Parse Anthropic Vision Output
let visionRawText = '';
try {
  const anthropicOutput = $input.first().json;
  visionRawText = anthropicOutput.content?.[0]?.text || '';
} catch (e) {}

// Clean JSON formatting
let cleanJson = visionRawText.replace(/```json\s*|\s*```/gi, '').trim();
let receiptData = {};
try {
  receiptData = JSON.parse(cleanJson);
} catch (e) {
  receiptData = { is_payment_receipt: false, raw_summary: visionRawText };
}

// Extract original prepData from previous node
let prepData = {};
try {
  prepData = $('Preparar Mensaje').first().json || {};
} catch (e) {}

const isReceipt = Boolean(receiptData.is_payment_receipt);
const isAppError = Boolean(receiptData.is_app_screenshot_or_error || receiptData.app_name || receiptData.detected_error);
const paymentMethod = String(receiptData.payment_method || 'unknown').toLowerCase();
const currency = String(receiptData.currency || 'USD').toUpperCase();
const amount = String(receiptData.amount || '').trim();
const dateTime = String(receiptData.date_time || '').trim();
const bankOrigin = String(receiptData.bank_origin || '').trim();
const refNumber = String(receiptData.reference_number || '').trim();
const destPhone = String(receiptData.destination_phone || '').trim();
const destRif = String(receiptData.destination_rif || '').trim();
const destEmail = String(receiptData.destination_email || '').trim().toLowerCase();
const brand = prepData.brand || 'totaltvusa';

let isVerified = false;
let verificationNotes = '';

if (isReceipt) {
  if (paymentMethod === 'pago_movil' || currency === 'VES' || currency === 'BS' || currency === 'BS.') {
    // Validate Pago Móvil destination details: Phone 04246861135 and RIF J405259221 / 405259221
    const cleanDestPhone = destPhone.replace(/\D/g, '');
    const cleanDestRif = destRif.replace(/[^0-9]/g, '');

    const phoneMatches = cleanDestPhone.endsWith('04246861135') || cleanDestPhone.endsWith('4246861135') || cleanDestPhone.includes('04246861135');
    const rifMatches = cleanDestRif.includes('405259221');

    if (phoneMatches && rifMatches) {
      isVerified = true;
      verificationNotes = 'VERIFIED_CORRECT: Pago Móvil realizado a teléfono oficial 04246861135 y RIF J405259221 (ArialStore C.A. / Bancamiga).';
    } else if (phoneMatches) {
      isVerified = true;
      verificationNotes = 'VERIFIED_CORRECT: Pago Móvil realizado a teléfono oficial 04246861135.';
    } else {
      isVerified = false;
      verificationNotes = `DISCREPANCIA DETECTADA: El Pago Móvil oficial es al teléfono 04246861135 RIF J405259221 (ArialStore C.A. / Bancamiga). La imagen indica teléfono: "${destPhone}", RIF: "${destRif}".`;
    }
  } else if (paymentMethod === 'zelle') {
    const expectedZelleEmail = (brand === 'tvtotal24') ? 'pagos@totaltvlatina.com' : 'acalimanr@gmail.com';
    if (destEmail.includes(expectedZelleEmail) || destEmail === expectedZelleEmail) {
      isVerified = true;
      verificationNotes = `VERIFIED_CORRECT: Pago Zelle realizado al correo oficial registrado (${expectedZelleEmail}).`;
    } else {
      isVerified = false;
      verificationNotes = `DISCREPANCIA DETECTADA: El correo Zelle oficial para ${brand === 'tvtotal24' ? 'TVTotal24' : 'TotalTv USA'} es "${expectedZelleEmail}". La imagen indica correo de destino "${destEmail}".`;
    }
  } else {
    // pd.cash, CashApp, NOWPayments, Card Payments, Binance, Stripe, PayPal, etc.
    isVerified = true;
    verificationNotes = `RECEIPT_RECEIVED: Comprobante de pago procesado vía ${paymentMethod.toUpperCase()} (pd.cash/pasarela/terceros). Se transmiten los datos extraídos para verificación y activación por agente humano.`;
  }
}

let receiptContextBlock = '';
if (isReceipt) {
  receiptContextBlock = `[PAYMENT RECEIPT DETECTED IN ATTACHMENT:
- Is Payment Receipt: TRUE
- Payment Method: ${paymentMethod.toUpperCase()}
- Amount: ${amount} ${currency}
- Date/Time: ${dateTime || 'N/A'}
- Bank / Platform Origin: ${bankOrigin || 'N/A'}
- Reference Number: ${refNumber || 'N/A'}
- Destination Phone in Receipt: ${destPhone || 'N/A'}
- Destination RIF/ID in Receipt: ${destRif || 'N/A'}
- Destination Email in Receipt: ${destEmail || 'N/A'}
- Destination Status: ${isVerified ? 'VERIFIED_CORRECT' : 'DISCREPANCY_DETECTED'}
- Verification Details: ${verificationNotes}
- MANDATE FOR AI:
  * IF Destination Status is VERIFIED_CORRECT (or payment via pd.cash / CashApp / NOWPayments / Card / Binance / Gateway): Thank the customer for sending their payment receipt (${paymentMethod.toUpperCase()}, amount: ${amount} ${currency}, ref: ${refNumber}), IMMEDIATELY execute Call 'transfer_to_human_tool' passing reason "Comprobante de Pago (${paymentMethod.toUpperCase()})" and case_details with all extracted payment details, and confirm to the customer that their payment receipt was received and passed to human support for activation/renewal.
  * IF Destination Status is DISCREPANCY_DETECTED: Politely inform the customer of the exact mismatch details (e.g., wrong Pago Móvil phone/RIF or Zelle email).]\n\n`;
} else if (isAppError) {
  const appName = String(receiptData.app_name || 'Desconocida').trim();
  const deviceType = String(receiptData.device_type || 'Desconocido').trim();
  const screenType = String(receiptData.screen_type || 'General').trim();
  const detectedError = String(receiptData.detected_error || 'Ninguno').trim();
  const diagnosisSummary = String(receiptData.app_diagnosis_summary || receiptData.raw_summary || visionRawText.slice(0, 250)).trim();

  receiptContextBlock = `[TECHNICAL SCREENSHOT DIAGNOSIS IN ATTACHMENT:
- Is Payment Receipt: FALSE
- Is App Screenshot / Technical Error: TRUE
- App Identified: ${appName}
- Device Identified: ${deviceType}
- Screen Type: ${screenType}
- Detected Error / Message: "${detectedError}"
- Technical Diagnosis & Solution: ${diagnosisSummary}
- MANDATE FOR AI AGENT:
  1. Acknowledge the screenshot sent by the customer and mention the app ("${appName}") and error/screen observed ("${detectedError}").
  2. Use this technical diagnosis context to provide precise, targeted troubleshooting steps to help the customer resolve their issue.
  3. If human support escalation is needed or requested, include App Name ("${appName}"), Device ("${deviceType}"), and Error ("${detectedError}") in BOTH 'reason' and 'case_details' when executing Call 'transfer_to_human_tool' so internal notes and admin notifications include full diagnostic data.]\n\n`;
} else if (visionRawText) {
  receiptContextBlock = `[IMAGE ATTACHMENT CONTEXT: The customer sent an image. Summary: "${receiptData.raw_summary || visionRawText.slice(0, 200)}"]\n\n`;
}

return [{
  json: {
    ...prepData,
    has_image: true,
    is_payment_receipt: isReceipt,
    is_app_screenshot_or_error: isAppError,
    receipt_data: receiptData,
    content: receiptContextBlock + (prepData.content || '')
  }
}];

// Node: Procesar Soporte TotalTv
const googleDocId = $vars.TOTALTV_SUPPORT_DOC_ID || '14VkDzxSnwQHZ6ezEZskeQ3lfLIXw5S0n2onK3I6yYdE';

let rawDocText = '';
let fetchSuccess = false;

if (googleDocId && googleDocId.length > 10) {
  try {
    const docRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://docs.googleapis.com/v1/documents/${googleDocId}`,
      headers: {
        'Authorization': `Bearer ${$credentials.googleSheetsOAuth2Api?.oauthTokenData?.access_token || ''}`
      },
      json: true
    });

    if (docRes && docRes.body && Array.isArray(docRes.body.content)) {
      let fullText = '';
      for (const element of docRes.body.content) {
        if (element.paragraph && Array.isArray(element.paragraph.elements)) {
          for (const elem of element.paragraph.elements) {
            if (elem.textRun && elem.textRun.content) {
              fullText += elem.textRun.content;
            }
          }
        }
      }
      rawDocText = fullText;
      fetchSuccess = true;
    }
  } catch (e) {}
}

let prepData = {};
try {
  prepData = $input.first().json || {};
} catch (e) {}

const brand = (prepData.brand || 'totaltvusa').toLowerCase();
const brandName = (brand === 'tvtotal24') ? 'TVTotal24' : 'TotalTv USA';
const now = new Date();

let supportContextBlock = '';

if (rawDocText) {
  const lines = rawDocText.split('\n');
  let currentSection = '';
  let tecnicaRules = [];
  let administrativaRules = [];

  const monthNames = {
    'enero': 0, 'febrero': 1, 'marzo': 2, 'abril': 3, 'mayo': 4, 'junio': 5,
    'julio': 6, 'agosto': 7, 'septiembre': 8, 'octubre': 9, 'noviembre': 10, 'diciembre': 11
  };

  for (let line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;

    if (/^#*\s*t[eé]cnica/i.test(trimmed)) {
      currentSection = 'TECNICA';
      continue;
    } else if (/^#*\s*administrativa/i.test(trimmed)) {
      currentSection = 'ADMINISTRATIVA';
      continue;
    } else if (/^#*\s*consultas\s+pendientes/i.test(trimmed) || /^#*\s*sin\s+respuesta/i.test(trimmed)) {
      currentSection = 'PENDIENTES';
      continue;
    }

    if (currentSection === 'TECNICA' || currentSection === 'ADMINISTRATIVA') {
      let ruleText = trimmed.replace(/^[-*\d\.\)]\s*/, '').trim();
      const lowerRule = ruleText.toLowerCase();

      const isTvTotal24Tag = lowerRule.includes('tvtotal24') || lowerRule.includes('tvtotal 24') || lowerRule.includes('latina');
      const isTotalTvUsaTag = lowerRule.includes('totaltv usa') || lowerRule.includes('totaltvusa') || lowerRule.includes('totaltv_usa');

      if (isTvTotal24Tag && brand !== 'tvtotal24') continue;
      if (isTotalTvUsaTag && brand === 'tvtotal24') continue;

      const dateMatch = lowerRule.match(/antes\s+del?\s+(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)(?:\s+de\s+(\d{4}))?/i);
      if (dateMatch) {
        const day = parseInt(dateMatch[1]);
        const monthIndex = monthNames[dateMatch[2].toLowerCase()];
        const year = dateMatch[3] ? parseInt(dateMatch[3]) : now.getFullYear();
        const targetDate = new Date(year, monthIndex, day, 23, 59, 59);

        if (now > targetDate) {
          ruleText += ` (Condición temporal: Fecha límite ${day} de ${dateMatch[2]} trascendida).`;
        }
      }

      if (currentSection === 'TECNICA') {
        tecnicaRules.push(ruleText);
      } else {
        administrativaRules.push(ruleText);
      }
    }
  }

  if (tecnicaRules.length > 0 || administrativaRules.length > 0) {
    supportContextBlock = `[DOCUMENTO DE SOPORTE TOTALTV SUPPORT (BASE DE CONOCIMIENTO VIVA PARA ${brandName.toUpperCase()}):\n`;
    if (tecnicaRules.length > 0) {
      supportContextBlock += `--- SECCIÓN TÉCNICA ---\n` + tecnicaRules.map(r => `• ${r}`).join('\n') + '\n';
    }
    if (administrativaRules.length > 0) {
      supportContextBlock += `--- SECCIÓN ADMINISTRATIVA ---\n` + administrativaRules.map(r => `• ${r}`).join('\n') + '\n';
    }
    supportContextBlock += `INSTRUCCIONES DE MÁXIMA PRIORIDAD PARA EL AGENTE DE IA:\n`;
    supportContextBlock += `1. Si la situación reportada por el cliente coincide con alguna de las instrucciones anteriores, APLICA DIRECTAMENTE LA SOLUCIÓN INDICADA EN EL DOCUMENTO para ayudar al cliente sin preguntas adicionales innecesarias.\n`;
    supportContextBlock += `2. NO realices transferencias a humano prematuras ni hagas preguntas genéricas cuando las instrucciones anteriores resuelven el caso.\n`;
    supportContextBlock += `3. Si logras resolver la situación del cliente con esta información, NO es necesario transferir a un asesor humano.\n`;
    supportContextBlock += `4. Si la situación del cliente NO está contemplada aquí ni en tu prompt y requiere atención personalizada, realiza la transferencia con Call 'transfer_to_human_tool'.]\n\n`;
  }
}

return [{
  json: {
    ...prepData,
    totaltv_support_doc_id: googleDocId,
    totaltv_support_active: fetchSuccess,
    content: supportContextBlock + (prepData.content || '')
  }
}];
